from PIL import Image
import numpy as np
im = np.array(Image.open('drawing.jpg').convert('RGB')).astype(int)
g = im.mean(axis=2)
R,G,B = im[:,:,0],im[:,:,1],im[:,:,2]
black = (g<90)&((R-B)<40)  # exclude brown
# horizontal runs
def hruns(y0,y1,x0,x1,minlen=40):
    out=[]
    for y in range(y0,y1):
        run=0
        for x in range(x0,x1):
            if black[y,x]: run+=1
            else:
                if run>=minlen: out.append((y,x-run,x-1,run))
                run=0
        if run>=minlen: out.append((y,x1-run,x1-1,run))
    return out
def vruns(y0,y1,x0,x1,minlen=40):
    out=[]
    for x in range(x0,x1):
        run=0
        for y in range(y0,y1):
            if black[y,x]: run+=1
            else:
                if run>=minlen: out.append((x,y-run,y-1,run))
                run=0
        if run>=minlen: out.append((x,y1-run,y1-1,run))
    return out
print('FRONT horizontal runs:')
for r in hruns(200,520,95,460,60): print(r)
print('FRONT vertical runs:')
for r in vruns(200,520,95,460,40): print(r)
"

